import{_ as a,o as i,c as e,aj as t}from"./framework.js";const c=JSON.parse('{"title":"导出站点 | Cli / Workflows | Documentation","description":"导出站点 in Kooboo: kb export 连接目标站点，让你选择要导出的资源组，并将结果下载为 ZIP 文件。","frontmatter":{"title":"导出站点 | Cli / Workflows | Documentation","description":"导出站点 in Kooboo: kb export 连接目标站点，让你选择要导出的资源组，并将结果下载为 ZIP 文件。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cli/workflows/export.html"}]]},"headers":[],"relativePath":"zh/cli/workflows/export.md","filePath":"cli/workflows/export.md","lastUpdated":1784361314000}'),l={name:"zh/cli/workflows/export.md"};function n(p,s,h,o,r,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="导出站点" tabindex="-1">导出站点 <a class="header-anchor" href="#导出站点" aria-label="Permalink to &quot;导出站点&quot;">​</a></h1><p><code>kb export</code> 连接目标站点，让你选择要导出的资源组，并将结果下载为 ZIP 文件。</p><h2 id="开始导出" tabindex="-1">开始导出 <a class="header-anchor" href="#开始导出" aria-label="Permalink to &quot;开始导出&quot;">​</a></h2><p>使用项目 <code>.env</code> 中的连接信息：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span></code></pre></div><p>执行过程中，CLI 会询问：</p><ul><li>导出文件名；</li><li>要包含的资源组；</li><li>是否把本次选择保存为下次默认值。</li></ul><p>未指定扩展名时，导出文件会使用 <code>.zip</code>。</p><h2 id="临时指定连接信息" tabindex="-1">临时指定连接信息 <a class="header-anchor" href="#临时指定连接信息" aria-label="Permalink to &quot;临时指定连接信息&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --site-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --username</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-username</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-password</span></span></code></pre></div><p>命令参数只影响本次导出。认证成功后，CLI 可能更新项目 <code>.env</code> 中的登录令牌，因此必须确保 <code>.env</code> 已被 Git 忽略。</p><h2 id="保存默认选择" tabindex="-1">保存默认选择 <a class="header-anchor" href="#保存默认选择" aria-label="Permalink to &quot;保存默认选择&quot;">​</a></h2><p>如果在交互过程中选择保存设置，CLI 会把默认导出资源组和文件名写入项目 <code>.env</code>：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_DEFAULT_EXPORTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Code,Script,Style</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_DEFAULT_FILE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=site.zip</span></span></code></pre></div><p>下次导出时仍会显示选择界面，可以继续调整资源范围。</p><h2 id="导出前后检查" tabindex="-1">导出前后检查 <a class="header-anchor" href="#导出前后检查" aria-label="Permalink to &quot;导出前后检查&quot;">​</a></h2><p>导出前：</p><ul><li>确认站点地址和账号；</li><li>为文件名加上日期或版本，避免覆盖旧备份；</li><li>确认磁盘空间足够。</li></ul><p>导出后：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><p>保存用于恢复的重要导出包时，不要只留在临时目录。导出成功只代表压缩包已下载，不代表其中包含所有业务数据；资源范围取决于交互时的选择。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./check-and-prune.html">资源对账与远端清理</a></li><li><a href="./push.html">推送本地资源</a></li></ul>`,23)])])}const u=a(l,[["render",n]]);export{c as __pageData,u as default};
